import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    last_o = history[-1][1]
    my_prev = history[-1][0]
    opp_c = sum(1 for x in history if x[1] == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in history if x[0] == 'C')
    my_d = n - my_c
    if n >= 2:
        opp_last2 = history[-2][1] + last_o
        if opp_last2 == 'CC':
            return 'C'
        if opp_last2 == 'DD':
            return 'C'
    if n > 20:
        tail = history[-20:]
        tail_opp_c = sum(1 for x in tail if x[1] == 'C')
        if tail_opp_c >= 18:
            return 'C'
        if tail_opp_c <= 2:
            return 'D'
    if n >= 4:
        recent = history[-4:]
        if all(x[1] == 'D' for x in recent):
            return 'D' if rng.random() < 0.2 else 'C'
    if opp_d == 0:
        return 'C'
    if opp_d == 1 and n >= 5:
        return 'C'
    ratio_d = opp_d / n
    if ratio_d > 0.8:
        return 'D'
    if n > 10:
        tail = history[-10:]
        tail_opp_d = sum(1 for x in tail if x[1] == 'D')
        if tail_opp_d >= 3:
            return 'D' if rng.random() < 0.4 else 'C'
    if last_o == 'D' and my_prev == 'C':
        return 'D' if rng.random() < 0.85 else 'C'
    if last_o == 'D':
        return 'D' if rng.random() < 0.6 else 'C'
    return 'C'
